"""Nightly revenue report."""
import fakedb

def build_report(day):
    orders = fakedb.query("SELECT id, customer_id, total FROM orders WHERE day = ?", day)
    lines = []
    for o in orders:
        cust = fakedb.query_one("SELECT name, region FROM customers WHERE id = ?", o["customer_id"])
        lines.append("%s,%s,%s,%s" % (o["id"], cust["name"], cust["region"], o["total"]))
    return "\n".join(lines)

if __name__ == "__main__":
    print(build_report("2026-07-08")[:200])

