"""Thin stand-in for the warehouse connection (eval fixture).
Each query pays a fixed round-trip; query volume, not the database, dominates runtime."""
import time

_ROUND_TRIP_S = 0.05

_CUSTOMERS = {i: {"name": "cust-%d" % i, "region": "NA" if i % 2 else "EU"} for i in range(1, 501)}
_ORDERS = [{"id": 8000 + i, "customer_id": (i % 500) + 1, "total": 20 + i % 80} for i in range(500)]

def query(sql, *params):
    time.sleep(_ROUND_TRIP_S)
    if "FROM orders" in sql:
        return list(_ORDERS)
    raise ValueError("unsupported query: " + sql)

def query_one(sql, *params):
    time.sleep(_ROUND_TRIP_S)
    if "FROM customers" in sql:
        return _CUSTOMERS[params[0]]
    raise ValueError("unsupported query: " + sql)

def query_many(sql, ids):
    """Batched lookup: one round-trip for any number of ids."""
    time.sleep(_ROUND_TRIP_S)
    if "FROM customers" in sql:
        return {i: _CUSTOMERS[i] for i in ids}
    raise ValueError("unsupported query: " + sql)
